export const clockDoodleCatalog=Object.freeze({
 all:['hedgehog','Ёж'],
 'd4cfd881-3f3d-4605-bdbe-eb470aa001e9':['duck','Утка'],
 '6c0fc11a-b532-4108-8aa7-b73e121892dc':['rocket','Ракета'],
