 const rows=[...D.byId.values()].map(p=>{const meta=D.metadata.get(p.userId),artist=artistIdentity(D,p.userId),state=D.participantOutcomes?.get(p.userId)?.officialOutcome?{status:D.participantOutcomes.get(p.userId).officialOutcome,count:p.scores.length,total:D.participantOutcomes.get(p.userId).scoreTotal,remaining:0}:participantStatus(p.scores),name=artist.displayName,battleName=artist.artistName;return {id:p.userId,name,battleName,forum:!!meta,veteran:meta?.group==='Ветераны'||meta?.veteran===true,scores:p.scores,...state,battleProfile:artist.profileUrl};});
 const forum=rows.filter(r=>r.forum),other=rows.filter(r=>!r.forum),veterans=forum.filter(r=>r.veteran);return {forum,other,veterans,forumStats:groupStats(forum),otherStats:groupStats(other),veteranStats:groupStats(veterans)};
}
export function groupStats(rows){const scores=rows.flatMap(r=>r.scores),passed=rows.filter(r=>r.status==='pass').length,failed=rows.filter(r=>r.status==='fail').length,pending=rows.length-passed-failed,decided=passed+failed;return {total:rows.length,passed,failed,pending,decided,passRate:decided?100*passed/decided:null,failRate:decided?100*failed/decided:null,scoreCount:scores.length,mean:mean(scores.map(s=>s.score)),meanCount:rows.length?scores.length/rows.length:null,distribution:Array.from({length:6},(_,v)=>scores.filter(s=>s.score===v).length)};}
export function selectForumRows(rows,{query='',status='all',group='all',sort='score'}={}){const q=query.trim().toLocaleLowerCase('ru-RU');const result=rows.filter(r=>(status==='all'||r.status===status)&&(group==='all'||(group==='veterans'?r.veteran:!r.veteran))&&r.name.toLocaleLowerCase('ru-RU').includes(q));return result.sort((a,b)=>{if(sort==='alpha')return alpha(a,b);return b.total-a.total||alpha(a,b);});}
export function forumStories(model){const complete=model.forum.filter(r=>r.remaining===0),stories=[];const highest=complete.filter(r=>r.status==='pass').sort((a,b)=>b.total-a.total||alpha(a,b))[0];if(highest)stories.push({title:'Самый уверенный проход',text:highest.name+' — '+highest.total+' баллов, все оценки получены.',id:highest.id});const closest=complete.slice().sort((a,b)=>Math.abs(a.total-config.passScore)-Math.abs(b.total-config.passScore)||alpha(a,b))[0];if(closest){const delta=closest.total-config.passScore;stories.push({title:'На тоненького',text:closest.name+' — '+(delta>=0?'прошёл с запасом '+delta+' балл(ов)':'не хватило '+(-delta)+' балл(ов)')+' (итог '+closest.total+', порог '+config.passScore+').',id:closest.id});}if(model.veterans.length)stories.push({title:'Последний из могикан',text:model.veterans.filter(r=>r.status!=='fail').length+' из '+model.veterans.length+' ветеранов ещё не выбыли.'});if(model.forumStats.pending)stories.push({title:'Никто не забыт',text:model.forumStats.pending+' участников форума ожидают недостающие оценки.'});return stories.slice(0,3);}

