 button.onclick=()=>list.hidden?open():close();
 button.onkeydown=e=>{if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();open(e.key==='Home'?0:e.key==='End'?items.length-1:select.selectedIndex);}};
