export const confidenceMethod='<p><strong>Активность:</strong> √(число оценённых форумщиков / 86). Используется только для личного индекса.</p>';
export const penaltyMethod='<p><strong>Уважение:</strong> 5 = +1, 4 = +0,5, 3 = 0, 2 = −0,5, 1 = −1; среднее × 15. Отдельных штрафов нет.</p>';
export const generalMethod='<p>Индекс ТУЗа показывает, как судьи относятся к форумным участникам и ветеранам баттла. Для каждой группы он рассчитывается отдельно.</p><p>Мы смотрим на три вещи:</p><p><strong>Благосклонность</strong> — насколько высокие оценки получает группа по сравнению с остальными участниками.</p><p><strong>Внимание</strong> — насколько раньше судьи оценивают участников группы относительно остальных.</p><p><strong>Уважение</strong> — какие оценки получает сама группа: высокие повышают показатель, низкие понижают, средние нейтральны.</p><p>Из этих показателей складывается общий индекс. Чем он выше, тем благоприятнее отношение судей к группе в рамках этой методики.</p>'; export const personalMethod='<p><strong>Личный ТУЗ = (60B + 25P + 15R) × √(Nг / размера группы).</strong> B — преимущество в средних оценках; P — насколько раньше судья оценивает форумщиков; R — уважение по оценкам (5 = +1, 4 = +0,5, 3 = 0, 2 = −0,5, 1 = −1). Nг — сколько участников выбранной группы оценил судья. Нет оценок одной из групп — индекс не рассчитывается. Диапазон −100…+100.</p>';
export const formulaMethod=confidenceMethod;

