import {musicAddButton} from './music-entry.6ec2835d2761e2fd.js';
import {commentsAction} from './r1-comments.6ec2835d2761e2fd.js';
import {selectForumRows} from './forum-link-model.6ec2835d2761e2fd.js';
import {selectMatrixRows} from './matrix-selection.6ec2835d2761e2fd.js';
// The live section supplies a projection of its official round context.
export function mountRapperReport(root,model,{page,round=1,participantId='',judgeId='',revealSelection=true,onChoose=()=>{},onJudge=()=>{},onNavigate=()=>{},allMembers=model.members}={}){
const report=root.querySelector('.rr-content'),params=new URLSearchParams();
if(participantId)params.set('participant',participantId);if(judgeId)params.set('judge',judgeId);
const members=model.members,byId=new Map(allMembers.map(p=>[p.id,p]));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=(n,d=2)=>Number.isFinite(n)?new Intl.NumberFormat('ru-RU',{maximumFractionDigits:d}).format(n):'—';
const groupName=p=>({forum:'Форум',veterans:'Ветераны',other:'Остальные',unknown:'Группа не подтверждена'}[p.group]);
const statusName=p=>round===2?'Сдал трек':({pass:'Прошёл',fail:'Вылетел',pending:'Ожидает решения'}[p.status]);
const safeProfile=p=>{try{const url=new URL(p.profile);return url.protocol==='https:'&&url.hostname==='19ib.ru'?url.href:null;}catch{return null;}};
let chosen=byId.has(participantId)?participantId:'';
let query=params.has('participant')&&members.some(p=>p.id===chosen)?byId.get(chosen).name:'',group='all',status='all',sort=round===2?'alpha':'score',limit=20;
let judge=model.judges.some(j=>j.id===params.get('judge'))?params.get('judge'):'all',judgeSort='',judgeDirection='desc',cell=null,opener=null;
if(page==='matrix'&&round===1&&innerWidth<=700&&!params.has('judge')){const seed=byId.get(chosen)||selectForumRows(members,{sort:'score'})[0],candidates=model.judges.filter(j=>seed?.scores.some(s=>s.judgeName===j.name));judge=[...candidates].sort((a,b)=>members.filter(p=>p.scores.some(s=>s.judgeName===b.name)).length-members.filter(p=>p.scores.some(s=>s.judgeName===a.name)).length)[0]?.id||'all';}
let selectedJudge=judge==='all'?'':judge;
const controller=new AbortController();
const dialog=root.querySelector('.rr-dialog'),dialogBody=dialog.querySelector('.rr-dialog-body');
function link(target,id=chosen,j=''){
 const url=new URL('rappers/',new URL('../',import.meta.url));url.searchParams.set('round',round);if(target==='matrix')url.searchParams.set('report',target);
 if(byId.has(id))url.searchParams.set('participant',id);if(target==='matrix'&&j)url.searchParams.set('judge',j);return url.href;
}
function choose(id){chosen=byId.has(id)?id:'';root.dataset.participant=chosen;onChoose(chosen);}
root.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||e.button||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;const url=new URL(a.href);if(url.origin!==location.origin||url.pathname!==new URL('rappers/',new URL('../',import.meta.url)).pathname)return;e.preventDefault();if(dialog.open)dialog.close();onNavigate(url.searchParams.get('report')||'participants',url.searchParams.get('participant')||chosen,url.searchParams.get('judge')||'');});
function announce(text){root.querySelector('.rr-live').textContent=text;}
function openDialog(html,trigger){opener=trigger||document.activeElement;dialogBody.innerHTML=html;if(!dialog.open)dialog.showModal();dialog.querySelector('.rr-close').focus();}
dialog.querySelector('.rr-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>{if(opener?.isConnected)opener.focus({preventScroll:true});});
dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();});
root.dataset.round=String(round);root.dataset.participant=chosen;
function heading(title,text,kicker=''){return `<header class="e6-heading">${kicker?`<span class="e6-kicker">${kicker}</span>`:''}<h2>${title}</h2><p>${text}</p></header>`;}
function segments(){return `<div class="e6-segments" role="group" aria-label="Группа участников">${[['all','Все'],['forum','Форум'],['veterans','Ветераны']].map(([key,label])=>`<button type="button" data-group="${key}" aria-pressed="${group===key}">${label}</button>`).join('')}</div>`;}
function tools(matrix=false){return `<form class="e6-tools" role="search"><label class="e6-search"><span class="rr-sr">Поиск по имени</span><input type="search" data-field="search" autocomplete="off" placeholder="Найти участника" value="${esc(query)}"></label>${segments()}<div class="e6-extra-filters"><button type="button" class="e6-filter-toggle" aria-expanded="false" aria-controls="rr-extra-${round}-${page}">Фильтры</button><div class="e6-extra-panel" id="rr-extra-${round}-${page}"><label class="e6-control"><span class="rr-sr">Результат</span><select data-field="status" aria-label="Результат"><option value="all">${round===1?'Все результаты':'Все сдачи'}</option>${round===1?'<option value="pass">Прошли</option><option value="fail">Вылетели</option>'+(members.some(p=>p.status==='pending')?'<option value="pending">Ожидают решения</option>':''):''}</select></label><label class="e6-control"><span class="rr-sr">Сортировка</span><select data-field="sort" aria-label="Сортировка участников"><option value="${round===1?'score':'alpha'}">${round===1?'По баллам':'По имени'}</option>${round===1?'<option value="alpha">По имени</option>':'<option value="time">Сначала сдавшие</option>'}${matrix?'<option value="alpha-desc">Я → А</option><option value="status">По результату</option><option value="judge">По оценке судьи</option>':''}</select></label><button type="button" class="e6-reset" data-reset>Сбросить</button></div></div></form>`;}
function wireTools(draw){
 const form=report.querySelector('.e6-tools'),disclosure=form.querySelector('.e6-extra-filters'),mq=matchMedia('(max-width:700px)');const toggle=disclosure.querySelector('.e6-filter-toggle'),panel=disclosure.querySelector('.e6-extra-panel');const expand=value=>{disclosure.dataset.expanded=String(value);panel.hidden=!value;toggle.setAttribute('aria-expanded',String(value));};const layout=()=>expand(!mq.matches);mq.addEventListener('change',layout,{signal:controller.signal});toggle.addEventListener('click',()=>expand(panel.hidden));disclosure.addEventListener('keydown',e=>{if(e.key==='Escape'&&mq.matches){expand(false);toggle.focus();}});layout();form.addEventListener('submit',e=>e.preventDefault());
 form.querySelector('[data-field="search"]').addEventListener('input',e=>{query=e.target.value;limit=20;draw();});
 form.querySelectorAll('[data-group]').forEach(b=>b.addEventListener('click',()=>{group=b.dataset.group;limit=20;form.querySelectorAll('[data-group]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));draw();}));
 form.querySelector('[data-field="status"]').addEventListener('change',e=>{status=e.target.value;limit=20;draw();});
 form.querySelector('[data-field="sort"]').addEventListener('change',e=>{sort=e.target.value;limit=20;draw();});
 form.querySelector('[data-reset]').addEventListener('click',()=>{query='';group='all';status='all';sort=round===1?'score':'alpha';judgeSort='';limit=20;if(page==='matrix'){judge='all';selectedJudge='';onJudge('');report.querySelector('[data-field="judge"]').value='all';}form.querySelector('[data-field="search"]').value='';form.querySelector('[data-field="status"]').value='all';form.querySelector('[data-field="sort"]').value=sort;form.querySelectorAll('[data-group]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.group==='all')));draw();});
}
function filtered(matrix=false){
 if(round===1){if(matrix)return selectMatrixRows(members,{query,group,status,matrixSort:sort==='judge'?'score':sort,judgeSort:sort==='judge'?model.judges.find(j=>j.id===(judgeSort||judge))?.name:null,judgeDirection});return selectForumRows(members,{query,group,status,sort});}
 const q=query.trim().toLocaleLowerCase('ru');return members.filter(p=>(group==='all'||p.group===group)&&p.name.toLocaleLowerCase('ru').includes(q)).sort((a,b)=>sort==='time'?Date.parse(a.submittedAt)-Date.parse(b.submittedAt)||a.id.localeCompare(b.id):a.name.localeCompare(b.name,'ru')||a.id.localeCompare(b.id));
}
function empty(text='Никого не нашли'){return `<div class="e6-empty" role="status"><span aria-hidden="true">∅</span><h3>${text}</h3><p>Попробуй другое имя или сбрось фильтры.</p></div>`;}
function profileHTML(p){const url=safeProfile(p);return url?`<a class="e6-text-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Профиль на 19ib.ru ↗</a>`:'';}
const included=p=>members.some(x=>x.id===p.id);
function personHTML(p){return `<div class="e6-person-detail" data-detail-id="${p.id}"><p class="e6-kicker">${esc(groupName(p))}</p><h3>${esc(p.name)}</h3><p class="e6-person-result">${round===1?`${fmt(p.total,0)} баллов · ${p.count} / 5 оценок`:`${p.durationSec??'—'} сек. · ${p.count??'—'} / 7 оценок`}</p><span class="e6-status e6-${p.status||'submitted'}">${statusName(p)}</span>${round===1?`<div class="e6-grades">${p.scores.map(s=>{const j=model.judges.find(j=>j.name===s.judgeName);return `<details><summary><span>${esc(s.judgeName)}</span><b>${s.score}</b></summary><p class="e6-comment">${esc(s.comment.trim()||'Комментария нет.')}</p>${j&&included(p)?`<a href="${esc(link('matrix',p.id,j.id))}">Эта оценка в матрице →</a>`:''}</details>`}).join('')}</div>`:'<p class="e6-note">Оценок и решения о проходе пока нет.</p>'}<div class="e6-detail-links">${musicAddButton(p.id,round)}${profileHTML(p)}${included(p)?`<a href="${esc(link('matrix',p.id))}">Матрица оценок →</a>`:''}</div></div>`;}
function showPerson(id,trigger){if(model.ensureComments&&!model.commentsReady()){const url=location.href;commentsAction(model.ensureComments,root,()=>showPerson(id,trigger),()=>!controller.signal.aborted&&location.href===url);return;}if(!byId.has(id))return;choose(id);const p=byId.get(id);if(innerWidth<=850||page==='matrix'||!members.some(p=>p.id===id)){openDialog(personHTML(p),trigger);return;}
 const host=report.querySelector('.e6-person-aside');host.innerHTML=`<button type="button" class="e6-inline-close" aria-label="Закрыть подробности участника">×</button>${personHTML(p)}`;host.hidden=false;report.querySelector('.e6-register').classList.add('has-detail');host.querySelector('.e6-inline-close').onclick=()=>{host.hidden=true;report.querySelector('.e6-register').classList.remove('has-detail');trigger?.focus({preventScroll:true});};
}
function participants(){
 const forum=members.filter(p=>p.group==='forum').length,veterans=members.filter(p=>p.group==='veterans').length,pass=members.filter(p=>p.status==='pass').length,fail=members.filter(p=>p.status==='fail').length,pending=members.filter(p=>p.status==='pending').length;
 report.innerHTML=heading(round===1?'Реестр баттла':'Подтверждённые сдачи',round===1?'Найди своего, посмотри результат и открой оценки.':'Второй раунд только собирается. Здесь — те, чьи сдачи уже подтверждены.')+`<section class="e6-summary" aria-label="Сводка участников"><div class="e6-summary-count"><strong>${members.length}</strong><span>${round===1?'наших участников':'подтверждённые сдачи'}</span></div><p><b>${round===2&&members.some(p=>p.group==='unknown')&&!forum?'—':forum}</b> Форум <span>·</span> <b>${round===2&&members.some(p=>p.group==='unknown')&&!veterans?'—':veterans}</b> Ветераны${round===2?' <small>группы сдающих пока не подтверждены</small>':''}</p>${round===1?`<div class="e6-summary-outcomes"><span><i class="e6-dot e6-pass"></i>${pass} прошли</span><span><i class="e6-dot e6-fail"></i>${fail} вылетели</span>${pending?`<span>${pending} ожидают решения</span>`:''}</div><div class="e6-outcome-bar" role="img" aria-label="Прошли ${pass}, вылетели ${fail}${pending?', ожидают '+pending:''}"><i class="e6-bar-pass" style="width:${100*pass/members.length}%"></i><i class="e6-bar-fail" style="width:${100*fail/members.length}%"></i>${pending?`<i style="width:${100*pending/members.length}%"></i>`:''}</div>`:'<p class="e6-note">Полный состав неизвестен. Итоги второго раунда ещё не опубликованы.</p>'}</section>`+tools()+`<p class="e6-results" role="status"></p><div class="e6-register"><section class="e6-list" aria-label="Участники"><div class="e6-row-head" aria-hidden="true"><span>Участник</span><span>Группа</span><span>${round===1?'Баллы':'Трек'}</span><span>Оценки</span><span>Результат</span></div><div class="e6-rows"></div><button type="button" class="e6-more">Ещё 20 участников ↓</button></section><aside class="e6-person-aside" aria-label="Участник" hidden></aside></div>`;
 const draw=()=>{
  const rows=filtered(),shown=rows.slice(0,limit);report.querySelector('.e6-results').textContent=`Показано ${shown.length} из ${rows.length}`;
  report.querySelector('.e6-rows').innerHTML=shown.map(p=>`${musicAddButton(p.id,round)?'<div class="music-rapper-row">':''}<button type="button" class="e6-person-row ${p.id===chosen?'is-selected':''}" data-person="${p.id}" aria-pressed="${p.id===chosen}"><strong>${esc(p.name)}</strong><span class="e6-row-group">${esc(groupName(p))}</span><span class="e6-row-score">${round===1?fmt(p.total,0):p.durationSec===null?'—':p.durationSec+' сек.'}</span><span class="e6-row-count">${p.count??'—'} / ${round===1?5:7}</span><span class="e6-status e6-${p.status||'submitted'}">${statusName(p)}</span></button>${musicAddButton(p.id,round)}${musicAddButton(p.id,round)?'</div>':''}`).join('')||empty();
  report.querySelector('.e6-more').hidden=limit>=rows.length;
  const aside=report.querySelector('.e6-person-aside');if(!rows.some(p=>p.id===chosen)){aside.hidden=true;report.querySelector('.e6-register').classList.remove('has-detail');}
 };
 wireTools(draw);report.querySelector('.e6-rows').addEventListener('click',e=>{const b=e.target.closest('[data-person]');if(!b)return;showPerson(b.dataset.person,b);report.querySelectorAll('[data-person]').forEach(x=>{x.classList.toggle('is-selected',x===b);x.setAttribute('aria-pressed',String(x===b));});});
 report.querySelector('.e6-more').onclick=()=>{const old=limit;limit+=20;draw();report.querySelectorAll('[data-person]')[old]?.focus({preventScroll:true});};draw();
 if(revealSelection&&params.has('participant')&&byId.has(chosen))showPerson(chosen,report.querySelector(`[data-person="${chosen}"]`));
}
function matrix(){
 if(round===2){report.innerHTML=heading('Матрица оценок','Кто кому и что поставил — как только появятся оценки.')+`<div class="e6-unavailable"><span class="e6-unavailable-mark" aria-hidden="true">＋</span><h3>Судьи ещё не вступили</h3><p>В доступных данных второго раунда нет состава судей и отдельных оценок. Заполнять матрицу пока нечем.</p><p class="e6-note">Подтверждены ${members.length} сдачи. Результаты первого раунда сюда не переносим.</p><a class="e6-action" href="${esc(link('participants'))}">Посмотреть сдачи →</a></div>`;return;}
 report.innerHTML=heading('Матрица оценок','Один трек, разные мнения. Выбери ячейку, чтобы прочитать комментарий.')+tools(true)+`<div class="e6-matrix-tools"><label>Судьи <select data-field="judge" aria-label="Показать судью"><option value="all">Все ${model.judges.length} судьи</option>${model.judges.map(j=>`<option value="${j.id}">${esc(j.name)}</option>`).join('')}</select></label><span class="e6-matrix-tip">Имена закреплены · матрицу можно листать ↔</span></div><p class="e6-results" role="status"></p><div class="e6-matrix-layout"><div class="e6-matrix-host"></div><aside class="e6-score-aside" aria-label="Выбранная оценка" hidden></aside></div><p class="e6-matrix-legend">Балл от 1 до 5 <span class="e6-grade-keys" aria-hidden="true">${[1,2,3,4,5].map(n=>`<i data-grade="${n}">${n}</i>`).join('')}</span><span>— нет оценки</span></p>`;
 const picker=report.querySelector('[data-field="judge"]');picker.value=judge;
 let visibleRows=[],cols=[];
 function highlight(rowId=cell?.p,colId=cell?.j){report.querySelectorAll('.e6-matrix-row').forEach(r=>r.classList.toggle('is-row',r.dataset.row===rowId));report.querySelectorAll('[data-j]').forEach(e=>{e.classList.toggle('is-col',e.dataset.j===colId);const active=e.dataset.p===cell?.p&&e.dataset.j===cell?.j;e.classList.toggle('is-cell',active);if(e.classList.contains('e6-cell'))e.setAttribute('aria-selected',String(active));});}
 function cellHTML(p,j){const score=p.scores.find(s=>s.judgeName===j.name);return `<div class="e6-score-detail" data-score-person="${p.id}" data-score-judge="${j.id}"><p class="e6-kicker">${esc(j.name)}</p><h3>${esc(p.name)}</h3><strong class="e6-grade-large">${score?.score??'—'}</strong><p class="e6-note">${score?'Оценка судьи':'Оценка этого судьи отсутствует'}</p>${score?`<p class="e6-comment">${esc(score.comment.trim()||'Комментария нет.')}</p>`:''}<a href="${esc(link('participants',p.id))}">Открыть участника →</a><div class="e6-detail-links">${musicAddButton(p.id,round)}${profileHTML(p)}</div></div>`;}
 function selectCell(pId,jId,trigger){if(model.ensureComments&&!model.commentsReady()){const url=location.href;commentsAction(model.ensureComments,root,()=>selectCell(pId,jId,trigger),()=>!controller.signal.aborted&&location.href===url);return;}const p=byId.get(pId),j=model.judges.find(j=>j.id===jId);if(!p||!j)return;cell={p:pId,j:jId};selectedJudge=jId;choose(pId);onJudge(jId);root.dataset.judge=jId;highlight();const html=cellHTML(p,j);
  if(innerWidth<=900){openDialog(html,trigger);return;}
  const aside=report.querySelector('.e6-score-aside');aside.hidden=false;aside.innerHTML=`<button type="button" class="e6-inline-close" aria-label="Закрыть выбранную оценку">×</button>${html}`;report.querySelector('.e6-matrix-layout').classList.add('has-detail');aside.querySelector('button').onclick=()=>{aside.hidden=true;report.querySelector('.e6-matrix-layout').classList.remove('has-detail');cell=null;highlight();trigger?.focus({preventScroll:true});};
  requestAnimationFrame(()=>trigger?.scrollIntoView({block:'nearest',inline:'nearest'}));announce(`${p.name}, ${j.name}: ${p.scores.find(s=>s.judgeName===j.name)?.score??'нет оценки'}`);
 }
 const draw=()=>{
  visibleRows=filtered(true);cols=judge==='all'?model.judges:model.judges.filter(j=>j.id===judge);const template=`var(--e6-name-width) repeat(${cols.length},var(--e6-cell-width))`;
  report.querySelector('.e6-results').textContent=`${visibleRows.length} участников · ${cols.length===1?'один судья':cols.length+' судьи'}`;
  report.querySelector('.e6-matrix-host').innerHTML=visibleRows.length?`<div class="e6-matrix-scroll" role="grid" aria-label="Оценки участников по судьям" aria-rowcount="${visibleRows.length+1}" aria-colcount="${cols.length+1}" tabindex="0"><div class="e6-matrix-header" role="row" style="grid-template-columns:${template}"><div class="e6-matrix-corner" role="columnheader">Участник</div>${cols.map(j=>`<div role="columnheader" class="e6-judge-name" data-j="${j.id}"><button type="button" data-judge-card="${j.id}" title="Карточка судьи">${esc(j.name)}</button><button type="button" data-sort-judge="${j.id}" aria-label="Сортировать по оценке ${esc(j.name)}">${judgeSort===j.id?(judgeDirection==='desc'?'↓':'↑'):'↕'}</button></div>`).join('')}</div>${visibleRows.map((p,r)=>`<div class="e6-matrix-row" role="row" data-row="${p.id}" style="grid-template-columns:${template}"><button type="button" class="e6-matrix-person" role="rowheader" data-open-person="${p.id}" title="${esc(p.name)}">${esc(p.name)}</button>${cols.map((j,c)=>{const score=p.scores.find(s=>s.judgeName===j.name);return `<button type="button" class="e6-cell" role="gridcell" tabindex="${r===0&&c===0?0:-1}" data-p="${p.id}" data-j="${j.id}" data-r="${r}" data-c="${c}" data-grade="${score?.score??'none'}" aria-label="${esc(p.name)}, ${esc(j.name)}: ${score?.score??'нет оценки'}">${score?.score??'—'}</button>`}).join('')}</div>`).join('')}</div>`:empty();highlight();
  if(cell&&(!visibleRows.some(p=>p.id===cell.p)||!cols.some(j=>j.id===cell.j))){report.querySelector('.e6-score-aside').hidden=true;report.querySelector('.e6-matrix-layout').classList.remove('has-detail');cell=null;}
 };
 wireTools(draw);picker.addEventListener('change',()=>{judge=picker.value;selectedJudge=judge==='all'?'':judge;onJudge(selectedJudge);draw();});
 const host=report.querySelector('.e6-matrix-host');
 host.addEventListener('click',e=>{const b=e.target.closest('.e6-cell'),name=e.target.closest('[data-open-person]'),head=e.target.closest('[data-sort-judge]');if(b)selectCell(b.dataset.p,b.dataset.j,b);else if(name)showPerson(name.dataset.openPerson,name);else if(head){judgeDirection=judgeSort===head.dataset.sortJudge&&judgeDirection==='desc'?'asc':'desc';judgeSort=head.dataset.sortJudge;sort='judge';report.querySelector('[data-field="sort"]').value='judge';draw();report.querySelector(`[data-sort-judge="${judgeSort}"]`)?.focus({preventScroll:true});}});
 host.addEventListener('pointerover',e=>{const b=e.target.closest('.e6-cell');if(b)highlight(b.dataset.p,b.dataset.j);});host.addEventListener('pointerleave',()=>highlight());
 host.addEventListener('focusin',e=>{const b=e.target.closest('.e6-cell');if(b){host.querySelectorAll('.e6-cell[tabindex="0"]').forEach(x=>x.tabIndex=-1);b.tabIndex=0;highlight(b.dataset.p,b.dataset.j);}});
 host.addEventListener('keydown',e=>{const b=e.target.closest('.e6-cell');if(!b||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();let r=Number(b.dataset.r),c=Number(b.dataset.c);if(e.key==='ArrowLeft')c--;if(e.key==='ArrowRight')c++;if(e.key==='ArrowUp')r--;if(e.key==='ArrowDown')r++;if(e.key==='Home')c=0;if(e.key==='End')c=cols.length-1;r=Math.max(0,Math.min(visibleRows.length-1,r));c=Math.max(0,Math.min(cols.length-1,c));host.querySelector(`.e6-cell[data-r="${r}"][data-c="${c}"]`)?.focus();});
 draw();if(revealSelection&&params.has('participant')&&params.has('judge')&&byId.has(chosen)&&judge!=='all'){const button=host.querySelector(`.e6-cell[data-p="${chosen}"][data-j="${judge}"]`);if(button)selectCell(chosen,judge,button);}
}
({participants,matrix}[page]||participants)();root.dataset.ready='true';
return {openPerson:showPerson,getJudge:()=>selectedJudge,destroy(){controller.abort();if(dialog.open)dialog.close();}};
}

