// Presentation copy only; calculations remain in the research models.
export function v58Method(kind,index,source){
 const history=' История восстановлена по датам оценок. Если их порядок нельзя определить надёжно, решающий судья не назначается. Поэтому в персональных итогах учтены не все проходы и вылеты.';
 const impact='Влияние = ТУЗ со всеми − ТУЗ без выбранного. Общий индекс пересчитывается целиком: средние оценки, порядок оценивания и веса. Индивидуальные влияния не складываются в общий индекс. Это изменение результата расчёта, а не доказательство причинной связи.';
 if(kind==='judges')return ({1:'Сравниваем личные показатели судей. Матрица 5×5 показывает оценки общим участникам; шкала 1–5, диагональ — равные баллы.',2:'Совместимость = 100 × (1 − MAE / 4). MAE — средняя абсолютная разница оценок на общих участниках. Точное совпадение — доля равных баллов. В рейтинг входят все пары хотя бы с одним общим треком. Пары без общих треков не имеют рассчитанной близости.',3:'Для трека с минимум 3 действительными оценками сравниваем оценку выбранного судьи со средним остальных судей этого же трека. Разница = оценка судьи − среднее коллег. MAE — среднее абсолютное значение этой разницы; рейтинг по MAE убывает и требует минимум 20 сравнений. Это величина расхождения, а не частота несогласия или оценка правоты. Треки отсортированы по модулю разницы. На общей шкале 1–5 каждый маркер показывает индивидуальную оценку; совпадающие оценки разнесены вертикально. Во вкладке «Спорные треки» используются пять действительных оценок: разброс равен максимуму минус минимум. По умолчанию показан разброс от 2; фильтры 4, 3 и 2 выбирают точное значение. Округление до двух десятичных знаков выполняется только при показе. Недействительные оценки исключаются действующей политикой раунда.',4:'Для каждого судьи выбираем самую быструю последовательную серию из 30 действительных оценок. Средний интервал — время от первой до последней оценки серии, делённое на 29 промежутков. Это время публикации оценок, а не длительность прослушивания. XSive MC и Бен Арфа отмечены отдельно: в таких марафонах не участвовали.',5:'Решающая — первая оценка, после которой сумма + свободные слоты ≥15 либо сумма + 5 × свободные слоты <15. Пятёрка не равна спасению, единица — казни. Доли считаются среди событий с определённым решающим судьёй.'+history}[index]||'Рейтинг строится по личному ТУЗу выбранной группы.');
 if(kind==='rappers')return index===2?impact+' Участник и его оценки исключаются из Форума; в остальных он не переводится. Ветераны остаются в сравнительной группе.':index===4?'Сумма, минимум и максимум считаются после каждой оценки при пяти слотах 1–5 и пороге 15. По горизонтали — номер оценки.'+history:'«На грани» — итоги 13–17 при пяти действительных оценках. Форум считается отдельно от Ветеранов. Незавершённые исходы показаны отдельно.';
 return ({0:'Проход гарантирован, когда сумма с минимальными оставшимися оценками достигает 15. Вылет — когда даже максимальные оставшиеся оценки не позволяют набрать 15. История показывает состояние на выбранную дату; позднейшие исправления оценок могли изменить прежние результаты.',1:'По дням показано число оценок за московские календарные сутки. Накопление — общее число оценок к концу каждого дня. Последний день может быть неполным.',2:'Часы определяются по московскому времени публикации оценок. Ночь — 00:00–05:59. Показано число оценок за весь период, без пересчёта на рабочие смены. Последний день может быть неполным.',3:'Нормальная модель — математический ориентир, построенный по распределению итоговых баллов. Она показывает, сколько участников ожидалось бы с каждой суммой при нормальном распределении. Это не прогноз решения судей и не доказательство нарушений.',4:'Интервал — время между соседними оценками судьи. Одновременные оценки дают интервал 0. Ночные и междневные паузы включены. Рейтинг требует ≥20 интервалов. Плотная серия — ≥3 оценки с промежутками ≤10/30/60 секунд. Лента показывает самую длинную серию, при равенстве — самую короткую по времени. Это время публикации оценок, а не прослушивания.',5:'Решающие события используют ту же выборку, что «Палачи и спасатели».'+history}[index]||'Активность показывает число действительных оценок по московскому времени публикации.');
}

export const distributionMethodDetails='Выборка: участники с пятью действительными оценками выбранной группы. Форум и Ветераны считаются отдельно по UUID. Среднее μ = Σx/N; σ = √(Σ(x−μ)²/N). Для целой суммы s вероятность p(s) = Φ((s+0,5−μ)/σ) − Φ((s−0,5−μ)/σ). Ожидаемое количество = N × p(s) / Σp(k), k=5…25. По согласованному изменению модель нормируется внутри границ 4,5–25,5: сумма ожиданий равна N с точностью вычислений. Ранее хвосты за пределами шкалы не перераспределялись, поэтому сумма ожиданий была меньше N. Доля = количество/N; для модели используется тот же N. Проход: факт — суммы 15–25, модель — сумма соответствующих ожиданий; разница = факт − модель. Округление только при показе. Для пустой выборки или нулевого разброса модель недоступна; малая выборка даёт менее устойчивый ориентир. Нормировка не меняет фактические результаты и порог 15.';

// Presentation paragraphs only: preserve every word and calculation description.
export function appendMethodParagraphs(root,text){
 for(const block of text.split(/(?<=\.) (?=Это величина|Во вкладке|Округление|В рейтинг|История)/)){
  const p=root.ownerDocument.createElement('p');p.textContent=block;root.append(p);
 }
}

